// The class skills ("the I key view"): one entry per skill with its rank
// ladder.  Generated by scripts/gen_skills.py from SPELLS.ZU1 (record layout:
// id @0, name @8, rank @71, point cost @107, effect f32 @127) + SPELLSEX.ZU1
// (help text with the same $ placeholders the pet spells use + the icon path;
// the ICON_<XX>_ prefix is the class, same two-letter map as the gear
// sprites).  Ranks 0..9: 'cost' is the skill points the upgrade costs (-1 =
// no further ranks), 'effect' is the rank's own number the desc placeholders
// resolve against.

export type SkillRank = { id: number; rank: number; need: number; effect: number };

// the per-rank $-placeholder slots (client.lto SkillData: EffectValueB,
// EffectDurationA/B, EffectAMeantime/BMeantime in ms); count/count_b are the
// tick counts the client derives as duration / meantime
export type SkillVals = {
  b: number;
  count: number;
  count_b: number;
  dur_a: number;
  dur_b: number;
  mean_a: number;
  mean_b: number;
};

export type Skill = {
  class: string;
  name: string;
  icon: string | null;
  desc: string;
  // the spell ids the ranks cover, rank 0 first
  ids: number[];
  // one row per rank: the upgrade cost (skill points; -1 = no further rank)
  // + the effect number
  ranks: SkillRank[];
  // the per-rank effect values decoded from the record's effect-slot
  // columns (rank 0 first, parallel to ranks/ids)
  vals?: SkillVals[];
};

// the shipped desc placeholders resolve from the effect columns decoded into
// `vals`: $d_a/$d_ga/$$_a = EffectValueA (the rank's own effect), $$_b =
// EffectValueB, $d_na/$d_nb = duration / meantime (the tick count), $f_ta =
// EffectDurationA, $f_tb = EffectDurationB, $f_ia = EffectAMeantime, $f_ib =
// EffectBMeantime.  Every one of those tokens sits where a number goes in the
// shipped sentence ("10 times within 20 sec"), so they resolve to the bare
// number and a slot the row leaves empty prints "?" instead of a made-up one.
export function resolveDesc(
  desc: string,
  effect: number,
  vals?: SkillVals,
): string {
  if (!desc.includes("$")) return desc;
  const num = (f: number) => `${+(f * 100).toFixed(1).replace(/\.0$/, "")}%`;
  const raw = (f: number) => `${+f.toFixed(1).replace(/\.0$/, "")}`;
  const sec = (ms: number) => (ms > 0 ? raw(ms / 1000) : "?");
  const times = (n: number) => (n > 0 ? `${n}` : "?");
  return desc
    .replace(/\$\$_a/g, num(effect))
    .replace(/\$\$_b/g, vals && vals.b > 0 ? num(vals.b) : "+?")
    .replace(/\$d_na/g, times(vals?.count ?? 0))
    .replace(/\$d_nb/g, times(vals?.count_b ?? 0))
    .replace(/\$d_ga|\$d_a/g, raw(effect))
    .replace(/\$f_ia/g, sec(vals?.mean_a ?? 0))
    .replace(/\$f_ib/g, sec(vals?.mean_b ?? 0))
    .replace(/\$f_tb/g, sec(vals?.dur_b ?? 0))
    .replace(/\$f_ta|\$f_ga/g, sec(vals?.dur_a ?? 0));
}

let cache: Promise<Skill[]> | null = null;

export function loadSkills(): Promise<Skill[]> {
  if (!cache) {
    cache = fetch("/data/skills.json").then(
      (r) => r.json() as Promise<Skill[]>,
    );
  }
  return cache;
}

// the skill names the talent-tree descriptions mention ("Teaches you X",
// "SS.X") — a single with one of these names is a skill tree passives list
let refsCache: Promise<Set<string>> | null = null;

export function loadSkillTreeRefs(): Promise<Set<string>> {
  if (!refsCache) {
    refsCache = fetch("/data/talentRefs.json").then(
      (r) => r.json() as Promise<string[]>,
    ).then((arr) => new Set(arr));
  }
  return refsCache;
}
